<script setup>
import { computed, ref, watch } from 'vue'
import { createDocumentTemplate, listDocumentTemplates, updateDocumentTemplate } from '../../officialdocApi'
const props = defineProps({ tenantId: { type: Number, required: true }, organizationId: { type: Number, required: true } })
const emit = defineEmits(['notice'])
const templates = ref([]); const loading = ref(false); const saving = ref(false); const editorMode = ref('list'); const editingId = ref(0); const form = ref(emptyForm())
function emptyForm() { return { name:'', code:'', description:'', category:'', body:'# 标题\n\n## 一、事项背景\n\n## 二、工作安排\n\n## 三、结语', variablesText:'', constraintsText:'', is_enabled:true } }
function splitLines(value) { return String(value || '').split(/[\n,，、]/).map((item) => item.trim()).filter(Boolean) }
function showError(error) { emit('notice', { type:'error', text:error?.message || '模板操作未完成。' }) }
const editorTitle = computed(() => editingId.value ? '编辑模板' : '新建模板')
async function load() { if (!props.tenantId || !props.organizationId) { templates.value=[]; return }; loading.value=true; try { templates.value=await listDocumentTemplates(props.tenantId, props.organizationId) || [] } catch (error) { showError(error) } finally { loading.value=false } }
function openCreate() { editingId.value=0; form.value=emptyForm(); editorMode.value='editor' }
function startEdit(template) { editingId.value=template.id; form.value={ name:template.name||'', code:template.code||'', description:template.description||'', category:template.category||'', body:template.body||'', variablesText:(template.variables||[]).join('\n'), constraintsText:(template.constraints||[]).join('\n'), is_enabled:template.is_enabled !== false }; editorMode.value='editor' }
function backToList() { editorMode.value='list'; editingId.value=0; form.value=emptyForm() }
async function save() { if (!props.organizationId) { showError(new Error('请先选择或加入一个组织。')); return }; saving.value=true; const payload={ organization_id:props.organizationId, name:form.value.name.trim(), code:form.value.code.trim(), description:form.value.description.trim(), category:form.value.category.trim(), body:form.value.body.trim(), variables:splitLines(form.value.variablesText), constraints:splitLines(form.value.constraintsText), is_enabled:form.value.is_enabled }; try { const isEditing=Boolean(editingId.value); if (isEditing) await updateDocumentTemplate(props.tenantId, editingId.value, payload); else await createDocumentTemplate(props.tenantId, payload); emit('notice',{ text:isEditing ? '模板已更新。' : '模板已创建。' }); backToList(); await load() } catch (error) { showError(error) } finally { saving.value=false } }
watch(() => [props.tenantId, props.organizationId], load, { immediate:true })
</script>

<template>
  <section class="page-stack"><article v-if="editorMode === 'list'" class="panel"><div class="directory-toolbar"><div class="heading-actions"><button class="primary" type="button" :disabled="!props.organizationId" @click="openCreate">＋ 新建模板</button><button class="text-button" type="button" :disabled="loading" @click="load">刷新</button></div><div class="template-summary"><span><b>{{ templates.length }}</b> 个模板</span><span><b>{{ templates.filter((item) => item.is_enabled).length }}</b> 个已启用</span><span>模板更新只应用于后续创建的任务</span></div></div><div v-if="loading" class="empty">正在读取模板…</div><div v-else-if="!templates.length" class="empty">还没有模板。先建立一份 Markdown 模板，写作任务才能受控生成。</div><div v-else class="template-list"><article v-for="template in templates" :key="template.id" class="template-card"><div><span class="category">{{ template.category || '未分类' }}</span><h3>{{ template.name }}</h3><code>{{ template.code }}</code><p>{{ template.description || '未填写用途说明' }}</p><div class="tags"><span v-for="constraint in template.constraints" :key="constraint">{{ constraint }}</span></div></div><aside><span :class="['enabled',{off:!template.is_enabled}]">{{ template.is_enabled ? '已启用' : '已停用' }}</span><button class="secondary" type="button" @click="startEdit(template)">编辑</button></aside></article></div></article>
    <article v-else class="panel template-editor-page"><header class="page-heading"><div><button class="back-button" type="button" @click="backToList">← 返回模板列表</button><p class="eyebrow">CONTROLLED TEMPLATE</p><h2>{{ editorTitle }}</h2></div></header><p class="editor-description">模板定义写作的结构、变量与约束；保存后只应用于后续创建的写作任务。</p><aside class="form-guidance"><span>01</span><div><strong>先定义模板规则</strong><p>填写适用场景、变量和约束，再用 Markdown 固化输出结构。</p></div></aside><form class="template-form" @submit.prevent="save"><label>模板名称<input v-model="form.name" required placeholder="例如：会议纪要" /></label><div class="two-columns"><label>模板代码<input v-model="form.code" :disabled="Boolean(editingId)" required placeholder="例如：meeting_minutes" /></label><label>分类<input v-model="form.category" placeholder="例如：行政公文" /></label></div><label>用途说明<input v-model="form.description" placeholder="说明此模板适用的写作场景" /></label><label>变量（每行一个）<textarea v-model="form.variablesText" rows="3" placeholder="例如：会议主题&#10;参会人员" /></label><label>约束（每行一个）<textarea v-model="form.constraintsText" rows="3" placeholder="例如：不得编造时间和数据&#10;正文使用正式书面语" /></label><label>Markdown 模板正文<textarea v-model="form.body" rows="12" required /></label><label class="toggle"><input v-model="form.is_enabled" type="checkbox" /> 在当前组织启用</label><footer class="form-actions"><button class="secondary" type="button" @click="backToList">取消</button><button class="primary" type="submit" :disabled="saving">{{ saving ? '保存中…' : editingId ? '保存模板' : '创建模板' }}</button></footer></form></article>
  </section>
</template>

