flex-wrap:wrap;gap:6px}.tags span{padding:4px 8px;border-radius:6px;color:#587168;background:#f0f5f1;font-size:12px}.empty{min-height:300px;display:grid;place-items:center;padding:28px;border:1px dashed #cfddd5;border-radius:12px;color:#708176;background:#fbfdfc;text-align:center}.primary,.secondary,.ghost,.text-button,.icon-button{font:inherit;cursor:pointer}.primary{min-height:40px;padding:0 14px;border:0;border-radius:9px;color:#fff;background:#17694f;box-shadow:0 1px 2px rgba(13,60,44,.18);font-weight:750}.primary:hover{background:#105a43}.secondary,.ghost{min-height:40px;padding:0 13px;border:1px solid #cfded5;border-radius:9px;color:#176851;background:#fff;font-weight:750}.secondary:hover,.ghost:hover{border-color:#91bda7;background:#f4faf6}.text-button{border:0;color:#176851;background:transparent;font-weight:700}.modal-backdrop{position:fixed;z-index:60;inset:0;display:grid;place-items:center;padding:20px;background:rgba(14,28,22,.46)}.modal-card{width:min(560px,100%);max-height:calc(100vh - 40px);overflow:auto;padding:30px;border:1px solid #e1e9e3;border-radius:16px;background:#fff;box-shadow:0 24px 72px rgba(0,0,0,.22)}.modal-card.wide{width:min(760px,100%)}.icon-button{display:grid;width:32px;height:32px;place-items:center;border:0;border-radius:8px;color:#52645a;background:#eff3f0;font-size:23px;line-height:1}.modal-heading{align-items:flex-start}.modal-card form{display:grid;gap:16px;margin-top:24px}.modal-card label{display:grid;gap:7px;color:#3b5b4e;font-size:13px;font-weight:750}.modal-card input,.modal-card textarea{width:100%;padding:11px 13px;border:1px solid #cfdcd4;border-radius:9px;resize:vertical;color:#1f3028;background:#fff;font:inherit;line-height:1.6}.modal-card input:focus,.modal-card textarea:focus{border-color:#4f9d7a;outline:0;box-shadow:0 0 0 3px rgba(79,157,122,.13)}.two-columns{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:end}.toggle{display:flex!important;min-height:42px;align-items:center;gap:8px;padding:0 12px;border:1px solid #cfdcd4;border-radius:9px;white-space:nowrap}.toggle input{width:auto}.modal-actions{justify-content:flex-end;padding-top:7px}@media(max-width:620px){.panel{padding:20px}.heading-actions{flex-wrap:wrap;justify-content:flex-end}.template-card{grid-template-columns:1fr;padding:17px}.template-card aside{justify-items:start}.two-columns{grid-template-columns:1fr}.toggle{width:fit-content}.modal-card{padding:22px}.template-summary{display:grid}}
</style>

